package com.example.rokidgeminisecretary;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Authenticated local UI snapshots and explicit commands. No Gemini or calendar writes. */
final class ConversationWorkspace {
 private static long receivedElapsed=-1,receivedWall=-1;
 static AtomicFile file(Context c,String name){return new AtomicFile(new File(c.getFilesDir(),"workspace-"+name+".gcm"));}
 static JSONObject read(Context c,String name)throws Exception{return new JSONObject(new String(DeviceSecrets.photos().decrypt(file(c,name).readFully()),StandardCharsets.UTF_8));}
 static void write(Context c,String name,JSONObject value)throws Exception{AtomicFile f=file(c,name);FileOutputStream out=null;try{out=f.startWrite();out.write(DeviceSecrets.photos().encrypt(value.toString().getBytes(StandardCharsets.UTF_8)));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 static synchronized JSONObject snapshot(Context c){try{JSONObject state=read(c,"state");long age=System.currentTimeMillis()-state.optLong("receivedAt");if(age<0||age>7200000){file(c,"state").delete();return new JSONObject();}long elapsed=android.os.SystemClock.elapsedRealtime();return state.put("connected",receivedWall==state.optLong("receivedAt")&&receivedElapsed>=0&&elapsed>=receivedElapsed&&elapsed-receivedElapsed<15000);}catch(Exception e){return new JSONObject();}}
 static synchronized void accept(Context c,JSONObject value)throws Exception{if(value.toString().length()>50000)throw new IOException("状態が大きすぎます");JSONObject safe=new JSONObject().put("at",value.getLong("at")).put("receivedAt",System.currentTimeMillis()).put("referenceMode",value.optString("referenceMode","auto")).put("referenceAt",value.optLong("referenceAt")).put("commandStatus",value.optString("commandStatus")).put("commandId",value.optString("commandId")).put("commandPhase",value.optString("commandPhase","UNCONFIRMED")).put("inboxTitle",value.optString("inboxTitle").substring(0,Math.min(200,value.optString("inboxTitle").length())));if(value.optJSONObject("calendarDraft")!=null)safe.put("calendarDraft",CalendarDraftEdits.publicCandidate(value.getJSONObject("calendarDraft"))).put("draftAt",value.optLong("draftAt"));JSONObject installation=value.optJSONObject("installation");if(installation!=null){long version=installation.optLong("version");if(version<1||version>1000000)throw new IOException("版番号を確認できません");JSONArray certificates=new JSONArray(),incoming=installation.optJSONArray("signingSha256");if(incoming!=null&&incoming.length()<=2)for(int i=0;i<incoming.length();i++){String cert=incoming.getString(i);if(!cert.matches("[a-f0-9]{64}"))throw new IOException("署名情報を確認できません");certificates.put(cert);}safe.put("installation",new JSONObject().put("version",version).put("debuggable",installation.optBoolean("debuggable")).put("signingSha256",certificates));}JSONObject dictionary=value.optJSONObject("pronunciation");if(dictionary!=null&&dictionary.has("text")){String raw=dictionary.getString("text");PronunciationPolicy.parse(raw);String revision=PronunciationPolicy.revision(raw);if(!revision.equals(dictionary.getString("revision")))throw new IOException("辞書の状態を確認できません");safe.put("pronunciation",new JSONObject().put("text",raw).put("revision",revision));}JSONObject latency=value.optJSONObject("latency");if(latency!=null){JSONObject clean=new JSONObject();for(String key:new String[]{"modelStartMs","firstTextMs","speechDispatchMs"})if(latency.has(key)){long ms=latency.optLong(key,-1);if(ms>=0&&ms<=600000)clean.put(key,ms);}clean.put("speechAudibleStart","unavailable").put("receivedAt",System.currentTimeMillis());safe.put("latency",clean);}JSONObject trace=value.optJSONObject("trace");if(trace!=null){String request=trace.optString("request");String phase=trace.optString("phase");safe.put("trace",new JSONObject().put("request",request.matches("[a-f0-9]{64}")?request:"").put("at",Math.max(0,trace.optLong("at"))).put("endedAt",Math.max(0,trace.optLong("endedAt"))).put("reference",trace.optString("reference").matches("auto|image|none|inbox")?trace.optString("reference"):"unknown").put("phase",phase.matches("RUNNING|RETURNED|FAILED")?phase:"UNKNOWN").put("responseObserved",trace.optBoolean("responseObserved")).put("searchObserved",trace.optBoolean("searchObserved")).put("queries",Math.max(0,Math.min(1000,trace.optInt("queries")))).put("sources",Math.max(0,Math.min(1000,trace.optInt("sources")))).put("contextChars",Math.max(0,Math.min(1000000,trace.optInt("contextChars")))));}
  JSONObject capture=value.optJSONObject("capture");if(capture!=null){String resource=capture.optString("resource");safe.put("capture",new JSONObject().put("meetingService",capture.optBoolean("meetingService")).put("keepService",capture.optBoolean("keepService")).put("imagePending",capture.optBoolean("imagePending")).put("videoPending",capture.optBoolean("videoPending")).put("resource",resource.substring(0,Math.min(120,resource.length()))).put("resourceAt",Math.max(0,capture.optLong("resourceAt"))));}
  JSONObject activity=value.optJSONObject("activity");if(activity!=null)safe.put("activity",AssistantActivityState.safe(activity));JSONObject conversation=value.optJSONObject("conversation");if(conversation!=null)safe.put("conversation",ConversationDeliveryState.safe(conversation));JSONObject referent=value.optJSONObject("referent");if(referent!=null)safe.put("referent",ConversationReferentPreview.safe(referent));JSONObject recognition=value.optJSONObject("recognition");if(recognition!=null)safe.put("recognition",new JSONObject().put("source",recognition.optString("source")).put("phase",recognition.optString("phase")).put("at",recognition.optLong("at")).put("text",recognition.optString("text").substring(0,Math.min(1200,recognition.optString("text").length()))));JSONArray transfers=value.optJSONArray("transfers");if(transfers!=null){JSONArray bounded=new JSONArray();for(int i=0;i<Math.min(2,transfers.length());i++)bounded.put(TransferProgressPolicy.safe(transfers.getJSONObject(i)));safe.put("transfers",bounded);}JSONObject health=value.optJSONObject("health");if(health!=null)safe.put("health",LocalHealthCheck.publicSummary(health));if(value.optJSONObject("departure")!=null)safe.put("departure",DeviceReadiness.safe(value.getJSONObject("departure")));if(value.optJSONObject("quiet")!=null)safe.put("quiet",QuietHoursPolicy.checked(value.getJSONObject("quiet")).put("revision",Math.max(0,value.getJSONObject("quiet").optLong("revision"))));if(value.optJSONArray("reservations")!=null)safe.put("reservations",ReservationReceiptPolicy.checked(value.getJSONArray("reservations")));write(c,"state",safe);receivedWall=safe.getLong("receivedAt");receivedElapsed=android.os.SystemClock.elapsedRealtime();}
 static synchronized JSONObject submit(Context c,JSONObject input)throws Exception{
  String id=input.getString("requestId"),action=input.getString("action");if(!WorkspaceCommandPolicy.validId(id)||!action.matches("reference|calendar_edit|quiet_config|conversation_reset|conversation_speech|pronunciation_save|pronunciation_preview"))throw new IOException("操作を確認してください");JSONObject command=new JSONObject().put("requestId",id).put("action",action).put("expiresAt",System.currentTimeMillis()+600000);
  if(action.equals("conversation_reset")){ConversationTools.requireNoPending(c);command.put("expiresAt",System.currentTimeMillis()+60000);}
  else if(action.equals("conversation_speech")){String op=input.getString("speechAction"),key=input.getString("answerKey");if(!op.matches("pause|resume|replay")||!TrackedWebRequest.validId(key))throw new IOException("読み上げ操作を確認してください");command.put("speechAction",op).put("answerKey",key).put("expiresAt",System.currentTimeMillis()+30000);}
  else if(action.startsWith("pronunciation_")){JSONObject state=snapshot(c),dictionary=state.optJSONObject("pronunciation");String revision=input.getString("baseRevision");if(!state.optBoolean("connected")||dictionary==null||!revision.matches("[a-f0-9]{64}")||!revision.equals(dictionary.optString("revision")))throw new IOException("メガネの辞書が更新・未取得です。接続して開き直してください");command.put("baseRevision",revision);if(action.equals("pronunciation_save")){String raw=input.getString("text");PronunciationPolicy.parse(raw);command.put("text",raw);}else{String sample=input.getString("sample");if(sample.trim().isEmpty()||sample.length()>160||PronunciationPolicy.replace(sample,PronunciationPolicy.parse(dictionary.getString("text"))).length()>500)throw new IOException("試聴文を短くしてください");command.put("sample",sample).put("expiresAt",System.currentTimeMillis()+30000);}}
  else if(action.equals("reference")){String mode=input.getString("mode");if(!mode.matches("auto|image|none"))throw new IOException("参照先が不正です");long reference=input.optLong("referenceAt");if(mode.equals("image")){JSONObject state=snapshot(c);long now=System.currentTimeMillis();if(reference<=0||reference!=state.optLong("referenceAt")||now<reference||now-reference>=ImageReferenceSummary.TTL)throw new IOException("画像が更新・失効しています。最新の参照を開き直してください");}command.put("mode",mode).put("referenceAt",reference);}
  else if(action.equals("quiet_config")){JSONObject state=snapshot(c);if(!state.optBoolean("connected")||state.optJSONObject("quiet")==null||state.getJSONObject("quiet").optLong("revision")!=input.getLong("baseRevision"))throw new IOException("静かな時間の設定が更新・未取得です。開き直してください");command.put("baseRevision",input.getLong("baseRevision")).put("config",QuietHoursPolicy.checked(input.getJSONObject("config")));}
  else{JSONObject state=snapshot(c);long at=state.optLong("draftAt");if(at<=0||at!=input.getLong("baseAt")||System.currentTimeMillis()-at<0||System.currentTimeMillis()-at>600000)throw new IOException("登録候補の期限切れ・更新を確認してください");JSONObject edit=CalendarDraftEdits.publicCandidate(CalendarDraftEdits.apply(state.getJSONObject("calendarDraft"),input.getJSONObject("candidate")));command.put("baseAt",at).put("candidate",edit);}
  String name="command-"+id;try{JSONObject old=read(c,name);if(!WorkspaceCommandPolicy.sameCommand(old,command))throw new IOException("同じ操作IDの内容が変わりました");if(!old.optBoolean("queued")){if(!WorkspaceCommandPolicy.pendingFresh(old,System.currentTimeMillis()))throw new IOException("操作の期限が切れています。現在の内容を確認してから新しく操作してください");if(!MainActivity.queueBridgeCommand(c,"__LOKI_WORKSPACE__:"+id,false))throw new IOException("送信待ちが満杯です");old.put("queued",true);write(c,name,old);}return new JSONObject().put("queued",true).put("duplicate",true);}catch(FileNotFoundException absent){}
  prune(c);write(c,name,command);if(!MainActivity.queueBridgeCommand(c,"__LOKI_WORKSPACE__:"+id,false)){file(c,name).delete();throw new IOException("送信待ちが満杯です");}command.put("queued",true);write(c,name,command);c.getSharedPreferences("workspace_control",0).edit().putString("latest",id).commit();if(action.equals("conversation_reset"))ConversationTools.topicQueued(c,id,command.getLong("expiresAt"));return new JSONObject().put("queued",true);
 }
 static JSONObject command(Context c,String id)throws Exception{if(!WorkspaceCommandPolicy.validId(id))throw new IOException("操作IDが不正です");return read(c,"command-"+id);}
 static void prune(Context c)throws Exception{File[] files=c.getFilesDir().listFiles((d,n)->n.matches("workspace-command-[a-f0-9-]{36}\\.gcm"));int count=0;if(files!=null)for(File f:files){String name=f.getName().substring(10,f.getName().length()-4);try{if(read(c,name).optLong("expiresAt")<System.currentTimeMillis()-600000)file(c,name).delete();else count++;}catch(Exception corrupt){count++;}}if(count>=32)throw new IOException("操作履歴がいっぱいです。期限切れ後に再操作してください");}
 private ConversationWorkspace(){}
}
